package org.amnezia.awg.desktop.util

import java.util.Properties

/** Build metadata generated by desktop/build.gradle.kts. */
object BuildInfo {
    /** Version of the desktop GUI, e.g. "1.0.2"; "dev" if the resource is missing. */
    val version: String by lazy {
        BuildInfo::class.java.getResourceAsStream("/amnezia-awg-version.properties")?.use { stream ->
            Properties().apply { load(stream) }.getProperty("version")
        } ?: "dev"
    }
}
